import sys
from typing import List, Tuple

def calculate_expected_time(n: int, r: int, tricks: List[Tuple[int, float, int]]) -> float:
    def dp(i: int, current_time: int) -> float:
        if i == len(tricks):
            return current_time if current_time < r else float('inf')

        t, p, d = tricks[i]
        if current_time + t >= r:
            return current_time + t if current_time + t < r else float('inf')

        # Option 1: Attempt the trick
        attempt_success = p * dp(i + 1, current_time + t)
        attempt_failure = (1 - p) * dp(i, current_time + t + d)

        # Option 2: Reset and try again
        reset = dp(0, 0)

        return min(attempt_success + attempt_failure, reset)

    return dp(0, 0)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    r = int(data[1])
    m = int(data[2])

    tricks = []
    index = 3
    for _ in range(m):
        t = int(data[index])
        p = float(data[index + 1])
        d = int(data[index + 2])
        tricks.append((t, p, d))
        index += 3

    result = calculate_expected_time(n, r, tricks)
    print(f"{result:.6f}")

if __name__ == "__main__":

